Here is a legacy access-log analyzer that nobody dares touch. Save as /workspace/loganalyze.py verbatim:

import sys
import re

total = 0
errors4 = 0
errors5 = 0
bytes_total = 0
by_path = {}
by_hour = {}
bad_lines = 0

def run(fname):
    global total, errors4, errors5, bytes_total, bad_lines
    for line in open(fname):
        m = re.match(r'(\S+) - - \[(\d+)/(\w+)/(\d+):(\d+):(\d+):(\d+) [^\]]+\] "(\w+) (\S+) [^"]*" (\d+) (\d+|-)', line)
        if m:
            total = total + 1
            hour = m.group(5)
            path = m.group(9)
            status = m.group(10)
            size = m.group(11)
            if status[0] == "4":
                errors4 = errors4 + 1
            else:
                if status[0] == "5":
                    errors5 = errors5 + 1
            if size != "-":
                bytes_total = bytes_total + int(size)
            if path in by_path:
                by_path[path] = by_path[path] + 1
            else:
                by_path[path] = 1
            if hour in by_hour:
                by_hour[hour] = by_hour[hour] + 1
            else:
                by_hour[hour] = 1
        else:
            bad_lines = bad_lines + 1

def summary():
    s = ""
    s += "requests: " + str(total) + "\n"
    s += "4xx: " + str(errors4) + "\n"
    s += "5xx: " + str(errors5) + "\n"
    s += "bytes: " + str(bytes_total) + "\n"
    s += "malformed: " + str(bad_lines) + "\n"
    tops = sorted(by_path.items(), key=lambda kv: (-kv[1], kv[0]))[:3]
    for p, c in tops:
        s += "top: " + p + " " + str(c) + "\n"
    peak = None
    peak_n = -1
    for h in sorted(by_hour.keys()):
        if by_hour[h] > peak_n:
            peak_n = by_hour[h]
            peak = h
    s += "peak hour: " + str(peak) + "\n"
    return s

if __name__ == "__main__":
    run(sys.argv[1])
    sys.stdout.write(summary())

